// Generates packages/core/src/font-data.ts: character widths of the three standard PDF fonts, taken from
// pdf-lib's built-in metrics. core uses them to lay text out identically in the editor and in the saved PDF.
//   pnpm gen-font-data
// A test (engine/test/freetext.test.ts) fails if the generated file ever disagrees with pdf-lib.
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { PDFDocument, StandardFonts } from '@cantoo/pdf-lib';

const FONTS = { sans: StandardFonts.Helvetica, serif: StandardFonts.TimesRoman, mono: StandardFonts.Courier } as const;

const pdf = await PDFDocument.create();
const fonts = Object.fromEntries(await Promise.all(Object.entries(FONTS).map(async ([k, v]) => [k, await pdf.embedFont(v)])));

// WinAnsi: Unicode code point -> byte, read back from pdf-lib's own encoder so we cannot disagree with it.
const chars = fonts.sans.getCharacterSet().filter((cp: number) => cp >= 32).sort((a: number, b: number) => a - b);
const byteOf = (cp: number): number => parseInt(fonts.sans.encodeText(String.fromCodePoint(cp)).toString().slice(1, -1), 16);

for (const key of ['serif', 'mono']) {
  const other = fonts[key].getCharacterSet().filter((cp: number) => cp >= 32).sort((a: number, b: number) => a - b);
  if (JSON.stringify(other) !== JSON.stringify(chars)) throw new Error(`${key} has a different character set`);
}

const lines: string[] = [
  '// GENERATED by packages/engine/scripts/gen-font-data.ts from pdf-lib\'s standard font metrics. Do not edit.',
  '',
  '/** [Unicode code point, WinAnsi byte] for every character the standard fonts can show. */',
  `export const WIN_ANSI: readonly (readonly [number, number])[] = [${chars.map((cp: number) => `[${cp},${byteOf(cp)}]`).join(',')}];`,
  '',
  '/** Advance widths in 1/1000 em, indexed by WinAnsi byte. */',
  'export const WIDTHS = {',
];
for (const key of Object.keys(FONTS)) {
  const widths = chars.map((cp: number) => `${byteOf(cp)}:${Math.round(fonts[key].widthOfTextAtSize(String.fromCodePoint(cp), 1000) * 1000) / 1000}`);
  lines.push(`  ${key}: { ${widths.join(', ')} },`);
}
lines.push('} as const satisfies Record<string, Record<number, number>>;', '');

const out = fileURLToPath(new URL('../../core/src/font-data.ts', import.meta.url));
writeFileSync(out, lines.join('\n'));
console.log(`wrote ${out}: ${chars.length} characters x ${Object.keys(FONTS).length} fonts`);
